using EnterpriseDocumentIntelligence.BuildingBlocks.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
public sealed record SearchRequest(string Query,int TopK=10);public sealed record SearchResult(Guid DocumentId,string Text,double Score,string Citation);
[ApiController,Route("api/v1/search"),Authorize]public sealed class SearchController(ICurrentUser user,ILogger<SearchController> log):ControllerBase{[HttpPost]public async Task<ActionResult<IReadOnlyList<SearchResult>>>Search(SearchRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Query))return BadRequest("Query is required");if(r.TopK is <1 or >50)return BadRequest("TopK must be 1-50");log.LogInformation("Hybrid RAG search Tenant={TenantId} User={UserId} QueryLength={Length}",user.TenantId,user.UserId,r.Query.Length);await Task.Delay(1,ct);return Ok(Array.Empty<SearchResult>());}}